export function hasLocaleTranslation(value, locale) {
  if (locale === 'en') return true;
  const dictionary = localeText[locale];
  return Boolean(dictionary && typeof value === 'string' && Object.hasOwn(dictionary, value.trim()));
}

const escapeRegExp = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
export function translateText(value, locale = 'en') {
  if (!localeText[locale] || typeof value !== 'string') return value;
  const dictionary = localeText[locale];
  const phrasePairs = Object.entries(dictionary).sort(([a], [b]) => b.length - a.length);
  const trimmed = value.trim();
  if (dictionary[trimmed]) return value.replace(trimmed, dictionary[trimmed]);
  let translated = value;
  for (const [english, translatedText] of phrasePairs) {
    if (english.length < 4) continue;
    const pattern = new RegExp(`(?<![\\p{L}\\p{N}_])${escapeRegExp(english)}(?![\\p{L}\\p{N}_])`, 'gu');
    translated = translated.replace(pattern, translatedText);
  }
  if (locale === 'tr') {
    return translated
      .replace(/Up to (\d+) Languages/g, '$1 dile kadar')
      .replace(/From AED ([\d,]+) \/ month/g, (_, amount) => `Başlangıç AED ${amount.replaceAll(',', '.')} / ay`)
      .replace(/AED ([\d,]+) \/ month/g, (_, amount) => `AED ${amount.replaceAll(',', '.')} / ay`)
      .replace(/From AED ([\d,]+) \/ year/g, (_, amount) => `Başlangıç AED ${amount.replaceAll(',', '.')} / yıl`)
      .replace(/AED ([\d,]+) \/ year/g, (_, amount) => `AED ${amount.replaceAll(',', '.')} / yıl`)
      .replace(/From AED ([\d,]+)/g, (_, amount) => `Başlangıç AED ${amount.replaceAll(',', '.')}`);
  }
  translated = translated.replace(/Up to (\d+) Languages/g, 'حتى $1 لغات')
    .replace(/(From )?AED ([\d,]+)\s*\/\s*month/g, (_, from, amount) => `${from ? 'ابتداءً من ' : ''}AED ${amount} / شهرياً`)
    .replace(/(From )?AED ([\d,]+)\s*\/\s*year/g, (_, from, amount) => `${from ? 'ابتداءً من ' : ''}AED ${amount} / سنوياً`)
    .replace(/(From )?AED ([\d,]+) one-time(?: setup)?(?: based on scope)?/g, (_, from, amount) => `${from ? 'ابتداءً من ' : ''}AED ${amount} لمرة واحدة`)
    .replace(/([\d,]+) AI interactions per month/g, '$1 تفاعل ذكاء اصطناعي شهرياً');
  return translated;
}

export function translationSourceForNode(currentValue, previousRecord) {
  return previousRecord && currentValue === previousRecord.translated
    ? previousRecord.source
    : currentValue;
}

export function readLocale(storage) {
  try {
    storage ??= globalThis.localStorage;
    const stored = storage?.getItem(LOCALE_STORAGE_KEY);
    if (stored === 'ar' || stored === 'tr' || stored === 'en') return stored;
  } catch { /* Continue to the first-party cookie fallback. */ }
  try {
    const cookie = globalThis.document?.cookie?.split(';').map((part) => part.trim()).find((part) => part.startsWith(`${LOCALE_STORAGE_KEY}=`));
    const stored = cookie?.slice(LOCALE_STORAGE_KEY.length + 1); return stored === 'ar' || stored === 'tr' ? stored : 'en';
  } catch { return 'en'; }
}

export function readLocaleFromSearch(search) {
  const locale = new URLSearchParams(search).get('locale');
  return locale === 'ar' || locale === 'tr' || locale === 'en' ? locale : null;
}

export function writeLocale(locale, storage) {
  const selected = locale === 'ar' || locale === 'tr' ? locale : 'en';
  try { storage ??= globalThis.localStorage; storage?.setItem(LOCALE_STORAGE_KEY, selected); } catch { /* Continue to the first-party cookie fallback. */ }
  try { if (globalThis.document) globalThis.document.cookie = `${LOCALE_STORAGE_KEY}=${selected}; Path=/; Max-Age=31536000; SameSite=Lax`; } catch { /* Preference storage is optional. */ }
  return selected;
}
